# Code generated by Claude
"""
Measurement only (David, 2026-10-28, items 1 to 3): the sag gap, PLACE OVER tilt and dip, joints at the ramp cap, place accuracy and the held-object compensation, from an episode recording.

    MUJOCO_GL=egl python experiments/comp_measure.py RECORDING_DIR OUT_DIR [--ramp SECONDS]

One MuJoCo process: the recording is replayed (src/replay.py, states verified bit-identical) with a step hook. Writes OUT_DIR/left_arm.npz, phases.json, summary.json in the format of
experiments/left_arm_motion_measure.py (so left_arm_motion_report.py gives the jerk tables), plus OUT_DIR/comp_metrics.json:
 * sag gap: at the first tick of PLACE: OVER, per joint, the recorded command of the previous tick (the skill's command, before the gravity feedforward) minus the measured joint;
 * PLACE OVER: peak tilt of the beaker's axis from the vertical (deg), hand dip = the pad centre's height at the phase start minus its lowest height in the phase (mm), peak beaker slide in the hand;
 * ramp cap: in the first ramp_s of PLACE OVER, the ticks with any joint's recorded command speed at the minimum-jerk cap (>= 0.97 of it, the cap delayed 3 ticks by the command bridge) and the seconds from the phase start to the last such tick;
 * place accuracy: the beaker's base against the hotplate centre at the last tick; the held mass compensated (recording's heldmass).
"""
import argparse
import json
import math
import os
import sys
from pathlib import Path

PROJECT_ROOT = Path(__file__).resolve().parent.parent
sys.path.insert(0, str(PROJECT_ROOT))
sys.path.insert(0, str(PROJECT_ROOT / "experiments"))
os.environ.setdefault("MUJOCO_GL", "egl")

import numpy as np  # noqa: E402

import src.replay as replay_mod  # noqa: E402
from src.gripper_geometry import gripper_frame  # noqa: E402
from src.rate_limit import min_jerk  # noqa: E402
from src.robot_helpers import arm_ids  # noqa: E402
from src.run_record import load_recording  # noqa: E402
from src.task_config import MINK_CFG, PICK_PLACE_CFG  # noqa: E402

BRIDGE_DELAY_TICKS = 3


def main(args):
    rec_dir, out = Path(args.recording), Path(args.out)
    out.mkdir(parents=True, exist_ok=True)
    meta = json.loads((rec_dir / "meta.json").read_text())
    rec = load_recording(rec_dir)
    ramp_s = args.ramp if args.ramp is not None else PICK_PLACE_CFG["phase_start_ramp_s"]
    S = {"ids": None, "t": [], "cmd": [], "q": [], "qd": [], "bk": [], "bq": [], "pad": []}
    MODEL = [None]

    def hook(step_count, data):
        m = MODEL[0]
        if S["ids"] is None:
            ids = arm_ids(m, "left")
            gf = gripper_frame(m, "left")
            S["ids"] = (ids, m.body("openarm_left_hand_tcp").id, np.asarray(gf["pad_center_in_tcp"], float), m.body("task_beaker").id)
        ids, tcp, pad_in, bb = S["ids"]
        S["t"].append(data.time)
        S["cmd"].append(data.ctrl[ids["act"]].copy())
        S["q"].append(data.qpos[ids["qadr"]].copy())
        S["qd"].append(data.qvel[ids["vadr"]].copy())
        S["bk"].append(data.xpos[bb].copy())
        S["bq"].append(data.xmat[bb].copy())
        S["pad"].append(data.xpos[tcp] + data.xmat[tcp].reshape(3, 3) @ pad_in)

    orig = replay_mod.run_loop

    def spy(model, data, sources, cfg, viewer=None):
        MODEL[0] = model
        return orig(model, data, sources, cfg, viewer=viewer)

    replay_mod.run_loop = spy
    r = replay_mod.replay_run(rec_dir, out_dir=out, video="none", verify=True, quiet=True, step_hook=hook)
    replay_mod.run_loop = orig
    print(f"replay ok {r['ok']} ticks {r['ticks']} mismatch {r['mismatch']}", flush=True)
    t, cmd, q, qd = (np.array(S[k]) for k in ("t", "cmd", "q", "qd"))
    bk, bq, pad = np.array(S["bk"]), np.array(S["bq"]), np.array(S["pad"])
    spt = int(round(len(t) / r["ticks"]))
    labels = meta["labels"]
    phases = []
    for i, l in enumerate(labels):
        key = l["label"].split(" [")[0].split("  (+")[0]
        end = labels[i + 1]["tick"] if i + 1 < len(labels) else r["ticks"]
        if phases and phases[-1][2] == key and phases[-1][1] == l["tick"]:
            phases[-1][1] = end
        else:
            phases.append([l["tick"], end, key])
    np.savez_compressed(out / "left_arm.npz", t=t, cmd=cmd, q=q, qd=qd, steps_per_tick=spt, tick_t=t[spt - 1::spt])
    np.savez_compressed(out / "pad_beaker.npz", t=t, pad=pad, beaker=bk, beaker_R=bq, cmd_pre=rec["ctrl"][:, :, arm_ids(MODEL[0], "left")["act"]], heldmass=rec["heldmass"] if rec.get("heldmass") is not None else np.zeros((1, 2)))
    (out / "phases.json").write_text(json.dumps([{"tick": a, "end_tick": b, "t_start": float(t[a * spt]) if a * spt < len(t) else None, "key": k} for a, b, k in phases], indent=1))
    (out / "summary.json").write_text(json.dumps({"replay_ok": bool(r["ok"]), "ticks": r["ticks"], "steps": len(t), "steps_per_tick": spt, "n_phases": len(phases)}, indent=1))

    M = {"replay_ok": bool(r["ok"]), "ramp_s": ramp_s}
    po = next(p for p in phases if "PLACE: OVER" in p[2])
    a, b = po[0], po[1]
    act = arm_ids(MODEL[0], "left")["act"]
    pre = rec["ctrl"][:, :, act]                                       # the skill's command (before the gravity feedforward), every step of every tick
    gap = pre[a - 1, -1] - q[a * spt - 1]                              # last step of the tick before PLACE OVER against the measured joints at the same moment
    M["sag_gap_rad"] = [float(x) for x in gap]
    M["sag_gap_max_rad"] = float(np.abs(gap).max())
    M["sag_gap_joints_1_4_7_rad"] = [float(gap[j]) for j in (0, 3, 6)]
    # the first tick's command against the measured joints (what the skill's reset sees)
    M["held_mass_kg_at_boundary"] = None if rec.get("heldmass") is None else [float(x) for x in rec["heldmass"][a]]
    s0, s1 = a * spt, b * spt
    zb = bq[s0:s1].reshape(-1, 3, 3)[:, :, 2]                          # the beaker's own z axis in the world
    tilt = np.degrees(np.arccos(np.clip(zb[:, 2], -1, 1)))
    M["place_over_peak_tilt_deg"] = float(tilt.max())
    M["place_over_hand_dip_mm"] = float(1000 * (pad[s0, 2] - pad[s0:s1, 2].min()))
    rel = bk[s0:s1] - pad[s0:s1]
    M["place_over_beaker_slide_mm"] = float(1000 * np.linalg.norm(rel - rel[0], axis=1).max())
    # joints at the ramp cap, per tick of the phase, from the recorded command at each tick's end
    tick_cmd = pre[:, -1, :]
    v = np.diff(tick_cmd, axis=0, prepend=tick_cmd[:1]) * 150.0        # rad/s per tick (index k = the tick k, from the command at the end of tick k - 1)
    dtk = 1.0 / 150.0
    n_ramp = math.ceil(round(ramp_s / dtk, 6))
    cap_ticks, last_cap = 0, None
    per_tick = []
    for k in range(min(n_ramp + 10, b - a)):
        kk = k - BRIDGE_DELAY_TICKS
        cap = MINK_CFG["max_joint_speed"] * min_jerk((kk + 1) * dtk / ramp_s) if 0 <= kk < n_ramp else np.inf
        atcap = [j + 1 for j in range(7) if np.isfinite(cap) and abs(v[a + k, j]) >= 0.97 * cap]
        per_tick.append(len(atcap))
        if atcap:
            cap_ticks += 1
            last_cap = k
    M["place_over_ramp_cap_ticks"] = cap_ticks
    M["place_over_ramp_cap_last_tick"] = last_cap
    M["place_over_ramp_cap_seconds_to_last"] = None if last_cap is None else (last_cap + 1) * dtk
    first_n = min(n_ramp, b - a)
    M["place_over_ticks_in_first_ramp_with_any_joint_at_cap"] = int(sum(1 for c in per_tick[:first_n] if c))
    M["place_over_ramp_ticks"] = first_n
    M["place_over_peak_cmd_speed_rad_s"] = float(np.abs(v[a:b]).max())
    # place accuracy: the beaker's base against the hotplate centre at the end (MOVED hotplate_xy of experiments/demo_video.py)
    from demo_video import MOVED  # noqa: E402 (the moved layout's hotplate centre)
    end = bk[-1]
    M["place_offset_from_hotplate_centre_mm"] = [float(1000 * (end[0] - MOVED["hotplate_xy"][0])), float(1000 * (end[1] - MOVED["hotplate_xy"][1]))]
    M["place_distance_from_hotplate_centre_mm"] = float(np.hypot(*M["place_offset_from_hotplate_centre_mm"]))
    M["final_beaker_xyz_m"] = [float(x) for x in end]
    M["final_tilt_deg"] = float(np.degrees(np.arccos(np.clip(bq[-1].reshape(3, 3)[2, 2], -1, 1))))
    M["phases"] = {p[2]: [p[0], p[1]] for p in phases}
    (out / "comp_metrics.json").write_text(json.dumps(M, indent=1))
    print(json.dumps(M, indent=1), flush=True)
    return 0 if r["ok"] else 1


if __name__ == "__main__":
    ap = argparse.ArgumentParser(description=__doc__.split("\n")[1])
    ap.add_argument("recording")
    ap.add_argument("out")
    ap.add_argument("--ramp", type=float)
    sys.exit(main(ap.parse_args()))
